  "/ueberuns/leitung/": "<title>Leitung der Pfarrei Sankt Bonifatius Frankfurt</title>\n<meta name=\"description\" content=\"Pfarrer, Pastoralteam, Pfarrgemeinderat und Verwaltungsrat der Pfarrei Sankt Bonifatius Frankfurt. Transparenz und Verantwortung für unsere Gemeinde.\">\n<meta property=\"og:site_name\" content=\"Sankt Bonifatius\">\n<meta property=\"og:locale\" content=\"de_DE\">\n<meta property=\"og:type\" content=\"article\">\n<meta property=\"article:author\" content=\"https://www.facebook.com/bonifatiusffm/\">\n<meta property=\"article:publisher\" content=\"https://www.facebook.com/bonifatiusffm/\">\n<meta property=\"og:title\" content=\"Leitung der Pfarrei Sankt Bonifatius Frankfurt\">\n<meta property=\"og:description\" content=\"Pfarrer, Pastoralteam, Pfarrgemeinderat und Verwaltungsrat der Pfarrei Sankt Bonifatius Frankfurt. Transparenz und Verantwortung für unsere Gemeinde.\">\n<meta property=\"og:image\" content=\"https://sanktbonifatius.de/uploads/2026/05/st-bonifatius-frankfurt.jpg\">\n<meta property=\"og:image:secure_url\" content=\"https://sanktbonifatius.de/uploads/2026/05/st-bonifatius-frankfurt.jpg\">\n<meta property=\"og:image:alt\" content=\"\">\n<meta name=\"twitter:card\" content=\"summary_large_image\">\n<meta name=\"twitter:title\" content=\"Leitung der Pfarrei Sankt Bonifatius Frankfurt\">\n<meta name=\"twitter:description\" content=\"Pfarrer, Pastoralteam, Pfarrgemeinderat und Verwaltungsrat der Pfarrei Sankt Bonifatius Frankfurt. Transparenz und Verantwortung für unsere Gemeinde.\">\n<meta name=\"twitter:image\" content=\"https://sanktbonifatius.de/uploads/2026/05/st-bonifatius-frankfurt.jpg\">\n<script type=\"application/ld+json\">\n{\"@context\":\"https://schema.org\",\"@graph\":[{\"@type\":\"WebPage\",\"name\":\"Leitung der Pfarrei – Pfarrgemeinderat &amp; Verwaltungsrat | Sankt Bonifatius Frankfurt\",\"description\":\"Pfarrer, Pfarrgemeinderat (12 Mitglieder) und Verwaltungsrat (11 Mitglieder) der Kath. Pfarrei Sankt Bonifatius Frankfurt am Main – Mitglieder, Aufgaben, Sitzungsprotokolle und Kontakt.\",\"url\":\"https://sanktbonifatius.de/ueberuns/leitung/\",\"breadcrumb\":{\"@type\":\"BreadcrumbList\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Startseite\",\"item\":\"https://sanktbonifatius.de/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Über uns\",\"item\":\"https://sanktbonifatius.de/ueberuns/\"},{\"@type\":\"ListItem\",\"position\":3,\"name\":\"Leitung &amp; Gremien\",\"item\":\"https://sanktbonifatius.de/ueberuns/leitung/\"}]}},{\"@type\":\"Person\",\"name\":\"Dr. Werner Otto\",\"jobTitle\":\"Pfarrer\",\"worksFor\":{\"@type\":\"CatholicChurch\",\"name\":\"Pfarrei Sankt Bonifatius Frankfurt\"},\"email\":\"&#109;&#x61;&#x69;l&#116;&#x6f;&#x3a;w&#46;&#x6f;t&#116;&#x6f;&#x40;s&#97;&#x6e;k&#116;&#x62;&#x6f;n&#105;&#x66;&#x61;&#116;&#x69;&#x75;s&#46;&#x64;&#x65;\",\"telephone\":\"+4969695975860\"},{\"@type\":\"CatholicChurch\",\"name\":\"Pfarrei Sankt Bonifatius Frankfurt\",\"url\":\"https://sanktbonifatius.de/\",\"telephone\":\"+49-69-69597585-0\",\"email\":\"info&#64;sanktbo&#110;&#105;&#102;&#97;&#116;&#105;&#117;&#115;&#46;&#100;&#101;\",\"address\":{\"@type\":\"PostalAddress\",\"streetAddress\":\"Holbeinstraße 70\",\"postalCode\":\"60596\",\"addressLocality\":\"Frankfurt am Main\",\"addressRegion\":\"Hessen\",\"addressCountry\":\"DE\"}},{\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"Was ist der Pfarrgemeinderat (PGR) und was entscheidet er?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Der Pfarrgemeinderat ist das demokratisch gewählte Beratungs- und Beschlussgremium der Pfarrei Sankt Bonifatius Frankfurt. Er besteht aus 12 gewählten Mitgliedern und berät gemeinsam mit dem Pfarrer über alle pastoralen Angelegenheiten. Die Amtszeit beträgt vier Jahre (aktuell 2023–2027). Sitzungen sind öffentlich und finden alle zwei Monate statt.\"}},{\"@type\":\"Question\",\"name\":\"Was macht der Verwaltungsrat der Pfarrei?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Der Verwaltungsrat vertritt die Pfarrei als Körperschaft öffentlichen Rechts. Er beschließt den Haushalt, verwaltet das Vermögen (Gebäude, Mieteinnahmen) und ist Dienstgeber für die Pfarreiangestellten. Vorsitzender kraft Amtes ist der Pfarrer.\"}},{\"@type\":\"Question\",\"name\":\"Können Gemeindemitglieder an PGR-Sitzungen teilnehmen?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Ja, PGR-Sitzungen sind öffentlich. Termine erhalten Sie beim Pfarrbüro (069†69597585-0) oder per E-Mail (&#x69;&#x6e;&#x66;&#x6f;&#x40;&#x73;&#x61;&#x6e;&#107;&#116;&#98;&#111;&#110;&#105;&#102;atiu&#x73;&#x2e;&#x64;&#x65;). Protokolle stehen als PDF auf der Website bereit.\"}},{\"@type\":\"Question\",\"name\":\"Wie kann ich mich in der Pfarrei Sankt Bonifatius Frankfurt ehrenamtlich engagieren?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Die Pfarrei bietet viele Möglichkeiten: Gottesdienstmitarbeit, Jugendarbeit, Caritas, Verwaltung u.v.m. Wenden Sie sich an das Pfarrbüro oder besuchen Sie die Seite „Mitmachen‘ auf unserer Website.\"}}]}]}\n</script>",
